    //    def = ค่าเดิม (สลับ 3ท่อน A[1.6"×4" โชว์4"] : 5ท่อน B[1"×1.6" โชว์1.6"] · ระยะ 2.5 · ไม่โครง) → ทุน/ขายคงเดิม (37,800)
