      //   ไวนิล 75 (เดิมคิดราคาใช้ 100 ตามชีตถอดทุน → จันทันน้อยไป 2 แนว) · ชินโคร์ทุกรุ่น 138
      // ตารางชนิดแผ่นต้องตรงกับ ROOF_SHEET ในใบตัด + การ map วัสดุใน from-recipe เป๊ะ
      //   กระจก/วัสดุที่ใบตัดไม่มีชนิดแผ่น → ใบตัด fallback เป็นไวนิล (75) คิดราคาต้องตามไปด้วย ไม่งั้นจันทันไม่เท่ากัน
      E1: "material.indexOf('เมทัล')>=0?100:(material==='ดีไลท์'?100:(material==='โพลีตัน'?122:(material.indexOf('ชินโคร์')>=0?138:75)))",
      E2: 'Math.ceil((W*100)/E1)+1',                 // จำนวนแนวจันทัน/เพลท
