      SCL: "(function(){var R=Math.ceil(Wc/138),D=Math.max(Dc,1),PR=(material==='ชินโคร์ Prime 10มม');var best=1e15;[3,4,5,6].forEach(function(L){if(L*100<D)return;if(PR&&(L===4||L===5))return;var t=Math.max(1,Math.trunc(L*100/D));var s=Math.ceil(R/t)*1.38*L;if(s<best)best=s;});return best<1e15?best:R*1.38*Math.ceil(D/100);})()",
      // ② คำนวณ ตรงไฟล์ตัดประกอบ "กันสาดเพิง"
      RAKE: 'Dc/Math.cos(7*Math.PI/180)',            // ยื่นเอียง = ยื่น ÷ cos(องศา) · องศา 7 ตามใบตัด
      BAYS: 'Math.max(1, E2-1)',                      // จำนวนช่อง = จันทันรวม − 1
