      ENDJ: '10.2',                                   // ปลายหลังคา = รางน้ำ → หักจันทัน 10.2 (แผง ⑦)
      nGutter: 'Math.ceil(Wc/600)',
      nChak: 'Math.ceil((W*100)/600)',
      nZ: 'Math.ceil((W*100)/600)',
      nSteel: 'E2 * Math.ceil((H*100)/600)',
